16	// V2: Public site payload caching with single-flight locking (prevents thundering herd). Handles 95% of traffic. Simplified in V2 — no more product payload caching.
17	class SiteCacheService
18	{
19	    private const MISS_SENTINEL = '__MISS__';
20	
21	    /** @var array<string, array<string, string|null>|null> */
22	    private array $brandPartnerEnrichmentCache = [];
23	
24	    public function __construct(private readonly CacheLockService $cacheLock) {}
25	
26	    /**
27	     * Returns the public_payload TTL with ±20% jitter applied.
28	     *
29	     * Mirrors CacheLockService::writeWithJitter's distribution so payload-cache
30	     * writes (which use raw Cache::put inside our manual single-flight) get the
31	     * same expiry-spreading behaviour as rememberLocked-managed entries.
32	     */
33	    private function jitteredPayloadTtl(): int
34	    {
35	        return (int) round((int) config('partna.cache.ttls.public_payload') * (0.8 + mt_rand(0, 4000) / 10000.0));
36	    }
37	
38	    /**
39	     * Get public site payload (MOST CRITICAL - 95% of traffic)
40	     *
41	     * IMPORTANT: This must match the PublicSiteController response shape exactly.
42	     */
43	    public function getPublicSitePayload(string $subdomain): ?array
44	    {
45	        $subdomain = strtolower($subdomain);
46	
47	        $key = CacheKeyGenerator::publicSitePayload($subdomain);
48	        $cached = Cache::get($key);
49	
50	        if ($cached === self::MISS_SENTINEL) {
51	            return null;
52	        }
53	        if (is_array($cached)) {
54	            // Backward-compatible cache healing for payload shape changes.
55	            // Older cache entries may not include `services`.
56	            if (array_key_exists('services', $cached)) {
57	                $cached = $this->ensureBlockCollections($cached);
58	                $cached = $this->ensureProfessionalType(
59	                    $cached,
60	                    (string) data_get($cached, 'professional.id', '')
61	                );
62	                $cached = $this->safeWithStorePayload(
63	                    $cached,
64	                    (string) data_get($cached, 'professional.id', ''),
65	                    $subdomain
66	                );
67	
68	                if (! array_key_exists('legal', $cached)) {
69	                    $cached['legal'] = null;
70	                }
71	
72	                // Always resolve image variant paths to URLs (handles pre-URL-resolution cache entries)
73	                $site = $cached['site'] ?? null;
74	                if (is_array($site)) {
75	                    $professionalId = (string) data_get($cached, 'professional.id', '');
76	                    $cached['site'] = $this->safeHydrateSitePayload(
77	                        $site,
78	                        $professionalId,
79	                        '',
80	                        $subdomain
81	                    );
82	                }
83	
84	                Cache::put($key, $cached, $this->jitteredPayloadTtl());
85	
86	                return $cached;
87	            }
88	            Cache::forget($key);
89	        }
90	
91	        // Cache miss — acquire a per-subdomain fill lock so only one process rebuilds
92	        // the payload from the DB view while concurrent requests wait (single-flight).
93	        $fillLock = Cache::lock('site:fill:'.$subdomain, 10);
94	
95	        try {
96	            // Block up to 5 s for the lock; raises LockTimeoutException if it can't.
97	            $fillLock->block(5);
98	        } catch (\Illuminate\Contracts\Cache\LockTimeoutException) {
99	            // Another process is (or was) filling the cache.
100	            // Return whatever is now in cache, or null if it's still a miss.
101	            $warm = Cache::get($key);
102	            if ($warm === self::MISS_SENTINEL) {
103	                return null;
104	            }
105	
106	            return is_array($warm) ? $warm : null;
107	        }
108	
109	        try {
110	            // Double-check: the lock winner may have filled the cache while we waited.
111	            $rechecked = Cache::get($key);
112	            if ($rechecked === self::MISS_SENTINEL) {
113	                return null;
114	            }
115	            if (is_array($rechecked) && array_key_exists('services', $rechecked)) {
116	                return $rechecked;
117	            }
118	
119	            $row = PublicSitePayload::query()
120	                ->whereRaw('lower(subdomain) = ?', [$subdomain])
121	                ->first();
122	
123	            // View only contains published sites; if not found, treat as 404.
124	            if (! $row) {
125	                // Negative-cache briefly to reduce DB load from bot scans.
126	                Cache::put($key, self::MISS_SENTINEL, now()->addSeconds(30));
127	
128	                return null;
129	            }
130	
131	            $payload = $row->payload ?? [];
132	
133	            // The view's COALESCE guarantees services is always a jsonb array,
134	            // so a missing key is the only thing we have to defend against.
135	            $services = $payload['services'] ?? [];
136	
137	            $site = $payload['site'] ?? null;
138	            if (is_array($site)) {
139	                $site = $this->safeHydrateSitePayload(
140	                    $site,
141	                    (string) ($row->professional_id ?? ''),
142	                    (string) ($row->site_id ?? ''),
143	                    $subdomain
144	                );
145	            }
146	
147	            // Must match the controller response shape exactly.
148	            $links = is_array($payload['links'] ?? null) ? array_values($payload['links']) : [];
149	            $sections = is_array($payload['sections'] ?? null) ? array_values($payload['sections']) : [];
150	            $existingBlocks = is_array($payload['blocks'] ?? null) ? array_values($payload['blocks']) : [];
151	
152	            $data = [
153	                'published' => true,
154	                'site' => $site,
155	                'professional' => $payload['professional'] ?? null,
156	                'theme' => $payload['theme'] ?? null,
157	                'services' => $services,
158	                'links' => $links,
159	                'sections' => $sections,
160	                'blocks' => $this->buildCombinedBlocksPayload($links, $sections, $existingBlocks),
161	                'legal' => $payload['legal'] ?? null,
162	                // Preserve the store sub-object from the source payload so that
163	                // withStorePayload() below can lift selected_products + commission
164	                // settings out of payload.store. Without this, the rebuilt $data
165	                // has no 'store' key and withStorePayload falls through to empty
166	                // defaults — the front-end would see no featured products even
167	                // though the view row contains them.
168	                'store' => $payload['store'] ?? null,
169	            ];
170	            $data = $this->ensureProfessionalType($data, (string) ($row->professional_id ?? ''));
171	            $data = $this->safeWithStorePayload($data, (string) ($row->professional_id ?? ''), $subdomain);
172	            $data = $this->safeApplyBrandImageFallbacks($data, $subdomain);
173	
174	            Cache::put($key, $data, $this->jitteredPayloadTtl());
175	
176	            return $data;
177	        } finally {
178	            $fillLock->release();
179	        }
180	    }
