182	    /**
183	     * @param  array<string, mixed>  $payload
184	     * @return array<string, mixed>
185	     */
186	    private function applyBrandImageFallbacks(array $payload): array
187	    {
188	        $professional = $payload['professional'] ?? null;
189	        if (! is_array($professional) || ($professional['professional_type'] ?? null) === 'brand') {
190	            return $payload;
191	        }
192	
193	        $affiliateId = (string) ($professional['id'] ?? '');
194	        if (empty($affiliateId)) {
195	            return $payload;
196	        }
197	
198	        // JSON column is affiliate-controlled; use it only as a hint for which brand is configured.
199	        $brandPartner = $payload['site']['settings']['brand_partner'] ?? null;
200	        if (! is_array($brandPartner) || empty($brandPartner['professional_id'])) {
201	            return $payload;
202	        }
203	
204	        $claimedBrandId = (string) $brandPartner['professional_id'];
205	
206	        // BrandPartnerLink is the consent record — verify before using any brand data.
207	        $link = BrandPartnerLink::where('affiliate_professional_id', $affiliateId)
208	            ->where('brand_professional_id', $claimedBrandId)
209	            ->first();
210	
211	        if (! $link) {
212	            Log::warning('Brand-partner enrichment skipped: no verified link in consent table.', [
213	                'affiliate_id' => $affiliateId,
214	                'brand_id' => $claimedBrandId,
215	            ]);
216	
217	            return $payload;
218	        }
219	
220	        // Resolve brand_id from the verified link record, never from the mutable JSON.
221	        $brandId = (string) $link->brand_professional_id;
222	        $brandSite = Site::query()
223	            ->where('professional_id', $brandId)
224	            ->first();
225	
226	        if (! $brandSite) {
227	            return $payload;
228	        }
229	
230	        // Brand placeholders now live in site_media (pool=design, purpose=placeholder).
231	        // The service resolves variant URLs; we project them to { url, alt_text }
232	        // to match the new Hydrogen brand-design response shape.
233	        $designMedia = app(\App\Services\Media\BrandDesignMediaService::class)
234	            ->listDesignMedia((string) $brandSite->id);
235	
236	        if (empty($designMedia['placeholders'])) {
237	            return $payload;
238	        }
239	
240	        $placeholderImages = array_map(
241	            fn (array $p) => [
242	                'url' => $p['url'],
243	                'alt_text' => $p['alt_text'],
244	            ],
245	            $designMedia['placeholders']
246	        );
247	
248	        $imageKeys = ['gallery', 'content_images'];
249	
250	        foreach ($imageKeys as $key) {
251	            if (! isset($payload['site'][$key]) || ! is_array($payload['site'][$key])) {
252	                continue;
253	            }
254	
255	            if (empty($payload['site'][$key])) {
256	                $payload['site'][$key] = $placeholderImages;
257	            }
258	        }
259	
260	        return $payload;
261	    }
