345	    /**
346	     * @param  array<string, mixed>  $site
347	     * @return array<string, mixed>
348	     */
349	    public function enrichSiteWithBrandPartnerRadius(array $site): array
350	    {
351	        $settings = is_array($site['settings'] ?? null) ? $site['settings'] : [];
352	        $brandPartner = is_array($settings['brand_partner'] ?? null)
353	            ? $settings['brand_partner']
354	            : (is_array($settings['brandPartner'] ?? null) ? $settings['brandPartner'] : []);
355	
356	        $professionalId = $brandPartner['professional_id'] ?? $brandPartner['professionalId'] ?? null;
357	        if (! is_string($professionalId) || trim($professionalId) === '') {
358	            return $site;
359	        }
360	
361	        $enrichment = $this->resolveBrandPartnerEnrichmentData(trim($professionalId));
362	        if (! is_array($enrichment)) {
363	            return $site;
364	        }
365	
366	        if ($this->isMissingBrandPartnerField($brandPartner, 'border_radius', 'borderRadius') && $this->isFilledString($enrichment['border_radius'] ?? null)) {
367	            $brandPartner['border_radius'] = $enrichment['border_radius'];
368	        }
369	        if ($this->isMissingBrandPartnerField($brandPartner, 'font_file_url', 'fontFileUrl') && $this->isFilledString($enrichment['font_file_url'] ?? null)) {
370	            $brandPartner['font_file_url'] = $enrichment['font_file_url'];
371	        }
372	        if ($this->isMissingBrandPartnerField($brandPartner, 'username', 'handle') && $this->isFilledString($enrichment['username'] ?? null)) {
373	            $brandPartner['username'] = $enrichment['username'];
374	        }
375	        if ($this->isMissingBrandPartnerField($brandPartner, 'first_name', 'firstName') && $this->isFilledString($enrichment['first_name'] ?? null)) {
376	            $brandPartner['first_name'] = $enrichment['first_name'];
377	        }
378	        if ($this->isMissingBrandPartnerField($brandPartner, 'last_name', 'lastName') && $this->isFilledString($enrichment['last_name'] ?? null)) {
379	            $brandPartner['last_name'] = $enrichment['last_name'];
380	        }
381	        if ($this->isMissingBrandPartnerField($brandPartner, 'border_color', 'borderColor') && $this->isFilledString($enrichment['border_color'] ?? null)) {
382	            $brandPartner['border_color'] = $enrichment['border_color'];
383	        }
384	        if ($this->isMissingBrandPartnerField($brandPartner, 'logo_letter_spacing', 'logoLetterSpacing') && $this->isFilledString($enrichment['logo_letter_spacing'] ?? null)) {
385	            $brandPartner['logo_letter_spacing'] = $enrichment['logo_letter_spacing'];
386	        }
387	        if ($this->isMissingBrandPartnerField($brandPartner, 'logo_font_size', 'logoFontSize') && $this->isFilledString($enrichment['logo_font_size'] ?? null)) {
388	            $brandPartner['logo_font_size'] = $enrichment['logo_font_size'];
389	        }
390	        if ($this->isMissingBrandPartnerField($brandPartner, 'border_width', 'borderWidth') && $this->isFilledString($enrichment['border_width'] ?? null)) {
391	            $brandPartner['border_width'] = $enrichment['border_width'];
392	        }
393	        if ($this->isMissingBrandPartnerField($brandPartner, 'general_spacing_padding', 'generalSpacingPadding') && $this->isFilledString($enrichment['general_spacing_padding'] ?? null)) {
394	            $brandPartner['general_spacing_padding'] = $enrichment['general_spacing_padding'];
395	        }
396	
397	        $settings['brand_partner'] = $brandPartner;
398	        $site['settings'] = $settings;
399	
400	        return $site;
401	    }
