403	    /**
404	     * @return array<string, string|null>|null
405	     */
406	    private function resolveBrandPartnerEnrichmentData(string $professionalId): ?array
407	    {
408	        if (array_key_exists($professionalId, $this->brandPartnerEnrichmentCache)) {
409	            return $this->brandPartnerEnrichmentCache[$professionalId];
410	        }
411	
412	        $partnerSite = Site::query()
413	            ->where('professional_id', $professionalId)
414	            ->first(['settings']);
415	
416	        $partnerProfessional = Professional::query()
417	            ->whereKey($professionalId)
418	            ->first(['handle', 'first_name', 'last_name']);
419	
420	        if (! $partnerSite && ! $partnerProfessional) {
421	            $this->brandPartnerEnrichmentCache[$professionalId] = null;
422	
423	            return null;
424	        }
425	
426	        $partnerSettings = is_array($partnerSite?->settings ?? null) ? $partnerSite->settings : [];
427	        $design = is_array($partnerSettings['design'] ?? null) ? $partnerSettings['design'] : [];
428	        $typography = is_array($design['typography'] ?? null) ? $design['typography'] : [];
429	        $resolved = [
430	            'username' => $this->normalizeString($partnerProfessional?->handle ?? null),
431	            'first_name' => $this->normalizeString($partnerProfessional?->first_name ?? null),
432	            'last_name' => $this->normalizeString($partnerProfessional?->last_name ?? null),
433	            'border_color' => $this->normalizeString($design['border_color'] ?? $design['borderColor'] ?? null),
434	            'border_radius' => $this->normalizeString($design['border_radius'] ?? $design['borderRadius'] ?? null),
435	            'border_width' => $this->normalizeString($design['border_width'] ?? $design['borderWidth'] ?? null),
436	            'general_spacing_padding' => $this->normalizeString($design['general_spacing_padding'] ?? $design['generalSpacingPadding'] ?? null),
437	            'font_file_url' => null,
438	            'logo_letter_spacing' => $this->normalizeString($typography['logo_letter_spacing'] ?? $typography['logoLetterSpacing'] ?? null),
439	            'logo_font_size' => $this->normalizeString($typography['logo_font_size'] ?? $typography['logoFontSize'] ?? null),
440	        ];
441	
442	        $this->brandPartnerEnrichmentCache[$professionalId] = $resolved;
443	
444	        return $resolved;
445	    }
