540	    /**
541	     * @param  array<int, mixed>  $links
542	     * @param  array<int, mixed>  $sections
543	     * @param  array<int, mixed>  $existingBlocks
544	     * @return array<int, array<string, mixed>>
545	     */
546	    private function buildCombinedBlocksPayload(array $links, array $sections, array $existingBlocks = []): array
547	    {
548	        if ($links === [] && $sections === []) {
549	            return array_values(array_filter($existingBlocks, fn ($block): bool => is_array($block)));
550	        }
551	
552	        $normalizedLinks = array_map(function ($block): array {
553	            $data = is_array($block) ? $block : [];
554	            $data['block_group'] = 'links';
555	
556	            return $data;
557	        }, $links);
558	
559	        $normalizedSections = array_map(function ($block): array {
560	            $data = is_array($block) ? $block : [];
561	            $data['block_group'] = 'sections';
562	
563	            return $data;
564	        }, $sections);
565	
566	        $combined = array_merge($normalizedLinks, $normalizedSections);
567	
568	        usort($combined, function (array $a, array $b): int {
569	            $aSort = (int) ($a['sort_order'] ?? PHP_INT_MAX);
570	            $bSort = (int) ($b['sort_order'] ?? PHP_INT_MAX);
571	            if ($aSort !== $bSort) {
572	                return $aSort <=> $bSort;
573	            }
574	
575	            $aId = (string) ($a['id'] ?? '');
576	            $bId = (string) ($b['id'] ?? '');
577	
578	            return $aId <=> $bId;
579	        });
580	
581	        return array_values($combined);
582	    }
