651	    private function resolveImageVariantUrlsInSite(array $site, string $siteId): array
652	    {
653	        // --- Collect all media IDs (images + videos) in one pass ---
654	        $allMediaIds = [];
655	        foreach (['gallery', 'content_images', 'gallery_videos', 'content_videos'] as $key) {
656	            foreach ($site[$key] ?? [] as $item) {
657	                if (is_array($item) && ! empty($item['id'])) {
658	                    $allMediaIds[] = $item['id'];
659	                }
660	            }
661	        }
662	
663	        // Single query: one DB round-trip for all variant rows across all media types.
664	        // Index as: media_id → artifact_type → variant_key → URL
665	        $mvByMedia = [];
666	        if ($allMediaIds !== []) {
667	            $allVariants = MediaVariant::query()
668	                ->whereIn('media_id', array_unique($allMediaIds))
669	                ->get();
670	
671	            foreach ($allVariants as $mv) {
672	                $mvByMedia[$mv->media_id][$mv->artifact_type][$mv->variant_key] = $mv->url;
673	            }
674	        }
675	
676	        // --- Images: resolve variant URLs ---
677	        foreach (['gallery', 'content_images'] as $key) {
678	            $items = $site[$key] ?? [];
679	            if (! is_array($items)) {
680	                continue;
681	            }
682	            foreach ($items as $i => $item) {
683	                if (! is_array($item) || empty($item['id'])) {
684	                    continue;
685	                }
686	                $mediaId = $item['id'];
687	                $pathVariants = $item['variants'] ?? [];
688	                if (! is_array($pathVariants)) {
689	                    continue;
690	                }
691	                $urlVariants = [];
692	                foreach ($pathVariants as $variantKey => $path) {
693	                    $url = $mvByMedia[$mediaId]['webp'][$variantKey] ?? null;
694	                    if ($url !== null) {
