696	                    }
697	                }
698	                $site[$key][$i]['variants'] = $urlVariants;
699	            }
700	
701	            usort($site[$key], function ($a, $b) {
702	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
703	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
704	                if ($aSort !== $bSort) {
705	                    return $aSort <=> $bSort;
706	                }
707	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
708	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
709	
710	                return $aId <=> $bId;
711	            });
712	        }
713	
714	        // --- Videos: resolve variant/stream/poster URLs ---
715	        foreach (['gallery_videos', 'content_videos'] as $key) {
716	            $items = $site[$key] ?? [];
717	            if (! is_array($items)) {
718	                continue;
719	            }
720	            foreach ($items as $i => $item) {
721	                if (! is_array($item) || empty($item['id'])) {
722	                    continue;
723	                }
724	                $mediaId = $item['id'];
725	                $byType = $mvByMedia[$mediaId] ?? [];
726	
727	                $site[$key][$i]['variants'] = $byType['mp4'] ?? [];
728	                $site[$key][$i]['streams'] = $byType['hls_playlist'] ?? [];
729	                $site[$key][$i]['poster'] = ($byType['poster']['poster'] ?? null);
730	            }
731	
732	            usort($site[$key], function ($a, $b) {
733	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
734	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
735	                if ($aSort !== $bSort) {
