737	                }
738	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
739	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
740	
741	                return $aId <=> $bId;
742	            });
743	        }
744	
745	        // Ensure video keys always exist even when there are no videos (backward-compat).
746	        $site['gallery_videos'] = $site['gallery_videos'] ?? [];
747	        $site['content_videos'] = $site['content_videos'] ?? [];
